from __future__ import annotations

from datetime import date

from fastapi.responses import HTMLResponse

from .web import dashboard_html


_OLD_CARD = '''<div class="card"><div class="section-title"><h2>💰 Surebet</h2></div><div class="surebet-buttons"><button onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button class="live-button" onclick="loadSurebetLive()">🔴 SUREBET EN VIVO · BUSCAR AHORA</button></div><div class="status muted" id="surebet-status">El modo EN VIVO no consulta la API hasta que pulses el botón.</div><div id="surebet" class="muted">Selecciona PRE-PARTIDO o EN VIVO.</div></div>'''

_NEW_CARD = '''<div class="card"><div class="section-title"><h2>💰 Surebet</h2></div><div class="surebet-buttons"><button id="surebet-pre-button" onclick="loadSurebetPre()">📅 SUREBET PRE-PARTIDO</button><button id="surebet-live-button" class="live-button" onclick="loadSurebetLive()">🔴 SUREBET EN VIVO · BUSCAR AHORA</button></div><div class="status muted" id="surebet-status">Listo. Pulsa PRE-PARTIDO para revisar las cuotas almacenadas o EN VIVO para actualizar las cuotas live.</div><div id="surebet-summary" class="surebet-summary"></div><div id="surebet" class="muted">Aún no se ha realizado una búsqueda de surebets.</div></div>'''

_OLD_JS = '''function renderSurebet(d){const rows=d.opportunities||[];if(!rows.length){surebet.innerHTML='<p>No hay surebets disponibles con los datos actuales.</p>';return}surebet.innerHTML='<table><thead><tr><th>Partido</th><th>Mercado</th><th>Línea</th><th>Resultado</th><th>Casa</th><th>Cuota</th><th>Margen</th><th>Acción</th></tr></thead><tbody>'+rows.flatMap(o=>Object.entries(o.outcomes||{}).map(([selection,q])=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td>${esc(o.line??'-')}</td><td class="strong">${esc(selection)}</td><td>${esc(q.bookmaker)}</td><td>${q.odds}</td><td class="profit">${(o.profit_margin*100).toFixed(2)}%</td><td><button class="verify-button" onclick="verifySurebet(${o.match_id})">🔍 VERIFICAR</button></td></tr>`)).join('')+'</tbody></table>'}
async function loadSurebetPre(){surebetStatus.textContent='PRE-PARTIDO: usando únicamente las cuotas almacenadas; no se consulta OddsPapi.';const r=await fetch('/api/v1/arbitrage/pre-match?limit=100');const d=await r.json();surebetStatus.textContent=`📅 PRE-PARTIDO · ${d.opportunities?.length||0} surebets detectadas · sin consulta nueva.`;renderSurebet(d)}
async function loadSurebetLive(){surebetStatus.textContent='🔄 Consultando SOLO eventos EN VIVO ahora...';surebet.innerHTML='<p>Buscando oportunidades live...</p>';try{const r=await fetch('/api/v1/arbitrage/live?limit=100&hours=1&limit_matches=20',{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Error al consultar live');surebetStatus.textContent=`🔴 EN VIVO actualizado ahora · ${d.sync.live_matches_seen||0} partidos live consultados · ${d.opportunities?.length||0} surebets. Pulsa VERIFICAR para confirmar una oportunidad.`;renderSurebet(d)}catch(e){surebetStatus.textContent='❌ No se pudo actualizar el radar live: '+e.message;surebet.innerHTML=''}}
async function verifySurebet(matchId){surebetStatus.textContent='🔍 Verificando SOLO este partido y recalculando la surebet...';try{const r=await fetch(`/api/v1/arbitrage/verify/${matchId}?limit=100`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Error de verificación');surebetStatus.textContent=`${d.surebet_confirmed?'✅ SUREBET CONFIRMADA':'⚠️ SUREBET YA NO CONFIRMADA'} · Solo se actualizó este partido · ${d.odds_seen} cuotas recibidas.`;renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error verificando: '+e.message}}'''

_NEW_JS = '''const $=id=>document.getElementById(id);const surebetBox=$('surebet'),surebetStatus=$('surebet-status'),surebetSummary=$('surebet-summary'),preButton=$('surebet-pre-button'),liveButton=$('surebet-live-button');function setSurebetBusy(busy){preButton.disabled=busy;liveButton.disabled=busy;preButton.style.opacity=busy?.65:1;liveButton.style.opacity=busy?.65:1}function renderSurebetSummary(mode,count,extra=''){surebetSummary.innerHTML=`<div class="metric">${mode}<b>${count}</b></div>${extra?`<div class="metric">${esc(extra)}</div>`:''}`}function renderSurebet(d){const rows=Array.isArray(d.opportunities)?d.opportunities:[];renderSurebetSummary(d.mode==='live'?'🔴 EN VIVO':'📅 PRE-PARTIDO',rows.length,d.refreshed_on_demand?'Cuotas actualizadas ahora':'Cuotas almacenadas');if(!rows.length){surebetBox.innerHTML='<p><strong>ℹ️ No hay surebets en este momento.</strong></p><p>El sistema revisó las cuotas disponibles y no encontró una combinación de arbitraje con margen positivo.</p>';return}surebetBox.innerHTML='<table><thead><tr><th>Partido</th><th>Mercado</th><th>Línea</th><th>Resultado</th><th>Casa</th><th>Cuota</th><th>Margen</th><th>Acción</th></tr></thead><tbody>'+rows.flatMap(o=>Object.entries(o.outcomes||{}).map(([selection,q])=>`<tr><td>${esc(o.match)}</td><td>${esc(o.market)}</td><td>${esc(o.line??'-')}</td><td class="strong">${esc(selection)}</td><td>${esc(q.bookmaker)}</td><td>${q.odds}</td><td class="profit">${(o.profit_margin*100).toFixed(2)}%</td><td><button class="verify-button" onclick="verifySurebet(${o.match_id})">🔍 VERIFICAR</button></td></tr>`)).join('')+'</tbody></table>'}async function readJsonResponse(response){let data={};try{data=await response.json()}catch(_){data={}}if(!response.ok)throw new Error(data.detail||`HTTP ${response.status}`);return data}async function loadSurebetPre(){setSurebetBusy(true);surebetStatus.textContent='🔄 Revisando surebets PRE-PARTIDO...';surebetBox.innerHTML='<p>Buscando oportunidades pre-partido...</p>';surebetSummary.innerHTML='';try{const r=await fetch('/api/v1/arbitrage/pre-match?limit=100',{cache:'no-store'});const d=await readJsonResponse(r);surebetStatus.textContent=d.opportunities?.length?`✅ PRE-PARTIDO · ${d.opportunities.length} surebets encontradas.`:'ℹ️ PRE-PARTIDO revisado · NO HAY SUREBET EN ESTE MOMENTO.';renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error PRE-PARTIDO: '+e.message;surebetBox.innerHTML='<p>El servidor no pudo completar la búsqueda. Revisa que la API esté ejecutándose.</p>'}finally{setSurebetBusy(false)}}async function loadSurebetLive(){setSurebetBusy(true);surebetStatus.textContent='🔄 Consultando eventos EN VIVO ahora...';surebetBox.innerHTML='<p>Buscando oportunidades live...</p>';surebetSummary.innerHTML='';try{const r=await fetch('/api/v1/arbitrage/live?limit=100&hours=1&limit_matches=20',{method:'POST',cache:'no-store'});const d=await readJsonResponse(r);const liveSeen=d.sync?.live_matches_seen||0;const oddsSaved=d.sync?.odds_saved||0;surebetStatus.textContent=d.opportunities?.length?`🔴 EN VIVO · ${liveSeen} partidos · ${oddsSaved} cuotas · ${d.opportunities.length} surebets.`:`ℹ️ EN VIVO actualizado · ${liveSeen} partidos · ${oddsSaved} cuotas · NO HAY SUREBET EN ESTE MOMENTO.`;renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error EN VIVO: '+e.message;surebetBox.innerHTML='<p>No se pudo completar la búsqueda EN VIVO. El error de la API se muestra arriba.</p>'}finally{setSurebetBusy(false)}}async function verifySurebet(matchId){surebetStatus.textContent='🔍 Verificando este partido...';try{const r=await fetch(`/api/v1/arbitrage/verify/${matchId}?limit=100`,{method:'POST',cache:'no-store'});const d=await readJsonResponse(r);surebetStatus.textContent=d.surebet_confirmed?'✅ SUREBET CONFIRMADA después de verificar.':'⚠️ YA NO HAY SUREBET en este partido después de verificar.';renderSurebet(d)}catch(e){surebetStatus.textContent='❌ Error verificando: '+e.message}}'''


def dashboard_response(today: date) -> HTMLResponse:
    html = dashboard_html(today)
    html = html.replace(_OLD_CARD, _NEW_CARD)
    html = html.replace(_OLD_JS, _NEW_JS)
    html = html.replace('.profit{font-weight:800}', '.profit{font-weight:800}.metric{background:#f4f6fa;border-radius:10px;padding:10px}.metric b{font-size:20px;display:block;margin-top:4px}')
    return HTMLResponse(html)
